const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'y₁ = 0.8 sin x' },
      { kind: 'text', payload: 'y₂ = 0.4 sin x' },
      { kind: 'text', payload: 'y = y₁ + y₂ = 1.2 sin x' },
      { kind: 'text', payload: '合成振幅 1.2' },
      { kind: 'text', payload: '0.8' },
      { kind: 'text', payload: '0.4' },
      { kind: 'text', payload: 'O' },
      { kind: 'text', payload: 'π/2' },
      { kind: 'text', payload: 'π' },
      { kind: 'text', payload: '3π/2' },
      { kind: 'text', payload: '2π' }
    ];
  },
  render: function (input, metrics) {
    var W = (input && input.viewport && input.viewport.widthDu) || 720;
    var H = (input && input.viewport && input.viewport.heightDu) || 440;
    if (!(W > 200)) { W = 720; }
    if (!(H > 200)) { H = 440; }

    var padL = 78, padR = 56, padT = 56, padB = 108;
    var x0 = padL;
    var x1 = W - padR;
    var yTop = padT;

    function tw(i, fb) {
      var m = metrics ? metrics[i] : null;
      if (m) {
        if (typeof m.width === 'number' && isFinite(m.width)) { return m.width; }
        if (typeof m.w === 'number' && isFinite(m.w)) { return m.w; }
        if (m.size && typeof m.size.width === 'number' && isFinite(m.size.width)) { return m.size.width; }
      }
      return fb;
    }

    var paths = [];
    var nodes = [];
    function addPath(id, commands, style) {
      paths.push({ id: id, commands: commands });
      var n = { type: 'path', pathId: id };
      if (style) {
        for (var key in style) {
          if (Object.prototype.hasOwnProperty.call(style, key)) { n[key] = style[key]; }
        }
      }
      nodes.push(n);
    }
    function addLabel(text, x, y, opts) {
      var n = { type: 'label', text: text, x: x, y: y };
      n.fontSize = (opts && opts.fontSize) || 13;
      n.fill = (opts && opts.fill) || '#1f2937';
      if (opts && opts.textAnchor) { n.textAnchor = opts.textAnchor; }
      nodes.push(n);
    }

    // 图例文本宽度优先测量，避免与波形冲突的下方布局
    var legW0 = tw(0, 118);
    var legW1 = tw(1, 118);
    var legW2 = tw(2, 168);

    var yBot = H - padB;
    if (yBot - yTop < 180) { yBot = yTop + 180; }
    if (yBot > H - 84) { yBot = H - 84; }
    var cy = (yTop + yBot) / 2;
    var unit = ((yBot - yTop) / 2) / 1.45;

    function X(t) { return x0 + t * (x1 - x0); }
    function Y(a) { return cy - a * unit; }

    // 坐标轴
    addPath('axisX', visualSdk.arrow(x0 - 26, cy, x1 + 18, cy, {}), { stroke: '#334155', strokeWidth: 1.4, fill: 'none' });
    addPath('axisY', visualSdk.arrow(x0, yBot + 18, x0, yTop - 18, {}), { stroke: '#334155', strokeWidth: 1.4, fill: 'none' });

    // 刻度
    var tickTs = [0, 0.25, 0.5, 0.75, 1];
    var i;
    var xt = [];
    for (i = 0; i < tickTs.length; i++) {
      xt = xt.concat(visualSdk.polyline([[X(tickTs[i]), cy - 5], [X(tickTs[i]), cy + 5]]));
    }
    addPath('tickX', xt, { stroke: '#334155', strokeWidth: 1.2, fill: 'none' });

    var tickA = [1.2, 0.8, 0.4, -0.4, -0.8, -1.2];
    var yt = [];
    for (i = 0; i < tickA.length; i++) {
      yt = yt.concat(visualSdk.polyline([[x0 - 5, Y(tickA[i])], [x0 + 5, Y(tickA[i])]]));
    }
    addPath('tickY', yt, { stroke: '#94a3b8', strokeWidth: 1.2, fill: 'none' });

    // 三条同频同相正弦波
    var N = 240;
    function wave(amp) {
      var pts = [];
      for (var j = 0; j <= N; j++) {
        var t = j / N;
        pts.push([X(t), Y(amp * Math.sin(2 * Math.PI * t))]);
      }
      return visualSdk.polyline(pts);
    }
    addPath('w1', wave(0.8), { stroke: '#2563eb', strokeWidth: 2, fill: 'none' });
    addPath('w2', wave(0.4), { stroke: '#16a34a', strokeWidth: 2, fill: 'none' });
    addPath('w3', wave(1.2), { stroke: '#dc2626', strokeWidth: 2.2, fill: 'none' });

    // 振幅标注：在 x = π/2 处标出 0.4、0.8 与合成振幅 1.2
    var xd = X(0.25);
    addPath('ampGuide', visualSdk.polyline([[xd, cy], [xd, Y(1.2)]]), { stroke: '#dc2626', strokeWidth: 1.2, fill: 'none', strokeDasharray: '6 5' });
    addPath('dot1', visualSdk.circle(xd, Y(0.8), 3.6), { fill: '#2563eb', stroke: '#2563eb', strokeWidth: 1 });
    addPath('dot2', visualSdk.circle(xd, Y(0.4), 3.6), { fill: '#16a34a', stroke: '#16a34a', strokeWidth: 1 });

    // 图例
    var legY = [H - 58, H - 28];
    var legend = [
      { text: 'y₁ = 0.8 sin x', color: '#2563eb', row: 0, w: legW0 },
      { text: 'y₂ = 0.4 sin x', color: '#16a34a', row: 0, w: legW1 },
      { text: 'y = y₁ + y₂ = 1.2 sin x', color: '#dc2626', row: 1, w: legW2 }
    ];
    var cursors = [x0, x0];
    for (i = 0; i < legend.length; i++) {
      var e = legend[i];
      var ly = legY[e.row];
      var cx = cursors[e.row];
      addPath('sw' + i, visualSdk.polyline([[cx, ly - 4], [cx + 26, ly - 4]]), { stroke: e.color, strokeWidth: 2.6, fill: 'none' });
      addLabel(e.text, cx + 34, ly, { fontSize: 13, fill: e.color, textAnchor: 'start' });
      cursors[e.row] = cx + 34 + e.w + 26;
    }

    // 坐标文字
    addLabel('O', x0 - 14, cy + 18, { fontSize: 12, fill: '#334155', textAnchor: 'middle' });
    var xtLab = ['π/2', 'π', '3π/2', '2π'];
    for (i = 0; i < 4; i++) {
      addLabel(xtLab[i], X(tickTs[i + 1]), cy + 20, { fontSize: 12, fill: '#334155', textAnchor: 'middle' });
    }
    addLabel('x', x1 + 20, cy - 14, { fontSize: 13, fill: '#334155', textAnchor: 'middle' });
    addLabel('y', x0 + 14, yTop - 6, { fontSize: 13, fill: '#334155', textAnchor: 'start' });

    // 振幅文字
    addLabel('合成振幅 1.2', xd + 12, Y(1.2) - 10, { fontSize: 13, fill: '#dc2626', textAnchor: 'start' });
    addLabel('0.8', xd - 10, Y(0.8) + 4, { fontSize: 12, fill: '#2563eb', textAnchor: 'end' });
    addLabel('0.4', xd - 10, Y(0.4) + 4, { fontSize: 12, fill: '#16a34a', textAnchor: 'end' });

    return {
      schemaVersion: 1,
      sceneId: 'fig-sine-superposition',
      revision: (input && input.revision) || 0,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: nodes }
    };
  }
};
